#[test]
fn painter_styles_match_js() {
    // The reference's own values are plain f64 arithmetic over `vnoise`/`fbm`,
    // which this port shares bit-for-bit, so the only divergence available is
    // `Math.pow`/`Math.sin` ULPs. 1e-9 on a 0-255 channel is ~4e-12 of full
    // scale -- far tighter than `golden_parity_render.rs`'s own 1e-4, because
    // there is no two-pass canopy closure here for ULPs to compound through.
    const TOL: f64 = 1e-9;
    let mut k = 0usize;
    let mut touched = 0usize;
    for (si, npr) in npr_settings().into_iter().enumerate() {
        let a = TerrainAppearance { npr, ..TerrainAppearance::default() };
        for (ci, c) in NPR_CASES.iter().enumerate() {
            let got = render::apply_npr(&a, (c[0], c[1], c[2]), c[3], c[4], c[5], (c[6], c[7]), c[8] as usize, c[9] as usize, 64);
            for (g, w, ch) in [(got.0, NPR_EXPECTED[k], 'r'), (got.1, NPR_EXPECTED[k + 1], 'g'), (got.2, NPR_EXPECTED[k + 2], 'b')] {
                assert!((g - w).abs() < TOL, "setting {si} case {ci} channel {ch}: got {g}, want {w}");
            }
            // Non-emptiness, explicitly: a block that silently did nothing
            // would pass every comparison above if the extractor had also
            // silently done nothing. At least one channel of at least one
            // case per setting must actually have moved.
            if (got.0 - c[0]).abs() > 1e-6 || (got.1 - c[1]).abs() > 1e-6 || (got.2 - c[2]).abs() > 1e-6 {
                touched += 1;
            }
            k += 3;
        }
    }
    assert!(touched >= npr_settings().len(), "the Painter block changed almost nothing -- {touched} of {} cases moved", NPR_CASES.len() * npr_settings().len());
}

#[test]
fn painter_is_inert_when_every_style_is_off() {
    let a = TerrainAppearance::default();
    for c in NPR_CASES.iter() {
        let got = render::apply_npr(&a, (c[0], c[1], c[2]), c[3], c[4], c[5], (c[6], c[7]), c[8] as usize, c[9] as usize, 64);
        assert_eq!(got, (c[0], c[1], c[2]));
    }
}

