#[test]
fn multi_sun_rig_matches_js() {
    let mut k = 0usize;
    for az in SUN_AZ {
        let a = TerrainAppearance { sun_az_deg: az, ..TerrainAppearance::default() };
        for n in SUN_NORMALS {
            let got = render::multi_sun_from_normal(&a, n[0], n[1], n[2]);
            assert!((got - SUN_EXPECTED[k]).abs() < 1e-12, "az {az} normal {n:?}: got {got}, want {}", SUN_EXPECTED[k]);
            k += 1;
        }
    }
    // The rig's ambient floor means nothing is ever fully black, which is the
    // whole point of it; assert that rather than trusting the numbers to say so.
    assert!(SUN_EXPECTED.iter().all(|&v| v >= 0.10 && v <= 1.0));
}

