#[test]
fn coast_distance_matches_js() {
    let got = render::coast_distance(&COAST_FIELD, 8, 6, 0.5);
    assert_eq!(got.len(), COAST_EXPECTED.len());
    for (i, (&g, &w)) in got.iter().zip(COAST_EXPECTED.iter()).enumerate() {
        assert!((g - w).abs() < 1e-6, "cell {i}: got {g}, want {w}");
    }
    // Shape, explicitly: land really is zero and open water really is not, so
    // an all-zero (or all-INF) transform cannot pass by accident.
    assert!(got.iter().any(|&v| v == 0.0) && got.iter().any(|&v| v > 2.0));
}

