#[test]
fn coastal_wave_lines_match_js() {
    let mut k = 0usize;
    let mut foamed = 0usize;
    for gw in WAVE_GW {
        for wd in WAVE_DIST {
            let a = TerrainAppearance { npr: Npr { waves: true, wave_dist: wd, ..Npr::default() }, ..TerrainAppearance::default() };
            for cd in WAVE_CD {
                let got = render::apply_waves(&a, (70.0, 96.0, 128.0), cd, gw);
                for (g, w, ch) in [(got.0, WAVE_EXPECTED[k], 'r'), (got.1, WAVE_EXPECTED[k + 1], 'g'), (got.2, WAVE_EXPECTED[k + 2], 'b')] {
                    assert!((g - w).abs() < 1e-9, "gw {gw} waveDist {wd} cd {cd} channel {ch}: got {g}, want {w}");
                }
                if (got.0 - 70.0).abs() > 1e-6 {
                    foamed += 1;
                }
                k += 3;
            }
        }
    }
    // Non-emptiness: some of these cells really are inside the foam band. A
    // transform that returned its input everywhere would otherwise "pass".
    assert!(foamed > 6, "only {foamed} sampled cells got any foam");
}
